# tests/test_undefined.py
import pytest

from dataclasses_json.undefined import _UndefinedParameterAction


@pytest.mark.parametrize("obj", [None, object(), 42, "s", {"a": 1}, [1, 2]])
def test__UndefinedParameterAction_handle_dump(obj):
    """Base implementation always returns an empty dict, for any object."""
    assert _UndefinedParameterAction.handle_dump(obj) == {}


def test__UndefinedParameterAction_handle_dump_returns_fresh_dict():
    """Each call returns a new dict, so callers can't corrupt shared state."""
    first = _UndefinedParameterAction.handle_dump(object())
    second = _UndefinedParameterAction.handle_dump(object())
    assert first == {} and second == {}
    assert first is not second


def test__UndefinedParameterAction_handle_dump_does_not_touch_obj():
    """The base impl must not read any attribute off the object."""

    class Exploding:
        def __getattr__(self, name):
            raise AssertionError(f"handle_dump read attribute {name!r}")

    assert _UndefinedParameterAction.handle_dump(Exploding()) == {}
```

Run: `pytest tests/test_undefined.py -k handle_dump -q`

Why these three: `handle_dump` is a non-abstract staticmethod on an ABC, so it's callable on the class without instantiation; it takes `obj` but ignores it â the parametrized case pins the return value, the identity check pins that it's not a shared mutable default, and the exploding object pins that it truly ignores its argument (that's the contract subclasses override).

